tasks.solution:
#!/usr/bin/env bash
set -euo pipefail

dir="${1:?укажите каталог для деплоя}"
[[ -d "$dir" ]] || { echo "каталог $dir не найден" >&2; exit 1; }
echo "деплоим из $dir"

cat > lib.sh <<'EOF'
parse_version() {
  [[ "$1" =~ ^v?([0-9]+\.[0-9]+\.[0-9]+)$ ]] || return 1
  echo "${BASH_REMATCH[1]}"
}
EOF
mkdir -p tests
cat > tests/lib.bats <<'EOF'
#!/usr/bin/env bats
setup() { source ./lib.sh; }

@test "извлекает версию" {
  run parse_version "v1.2.3"
  [ "$status" -eq 0 ]
  [ "$output" = "1.2.3" ]
}

@test "падает на мусоре" {
  run parse_version "nope"
  [ "$status" -ne 0 ]
}
EOF
bats tests/
